package com.fullviewsdk

import androidx.fragment.app.FragmentActivity
import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReadableArray
import com.facebook.react.bridge.ReactApplicationContext
import io.fullview.fullview_sdk.Fullview
import io.fullview.fullview_sdk.FullviewSessionState
import io.fullview.fullview_sdk.HostType
import io.fullview.fullview_sdk.Region

/**
 * TurboModule over the native Fullview Android SDK. `NativeFullviewSdkSpec` is
 * generated by codegen from src/NativeFullviewSdk.ts.
 */
class FullviewSdkModule(reactContext: ReactApplicationContext) : NativeFullviewSdkSpec(reactContext) {

  private var sdk: Fullview? = null

  // The workspace, remembered here the way the web SDK's script tag carries it, rather than
  // repeated with every customer.
  private var workspace: Pair<Region, String>? = null

  override fun configure(region: String, organisationId: String, promise: Promise) {
    workspace = Region.valueOf(region.uppercase()) to organisationId

    if (sdk != null) {
      promise.resolve(null)
      return
    }
    val activity = reactApplicationContext.currentActivity
    if (activity == null) {
      promise.reject("INIT_ERROR", "No current activity; call init() once the app is mounted.")
      return
    }
    activity.runOnUiThread {
      try {
        val instance = Fullview().also { it.attach(activity, HostType.REACT_NATIVE) }
        // attach() commits the SDK fragment asynchronously; flush it so the fragment
        // has an activity by the time registerCustomer() runs.
        (activity as? FragmentActivity)?.supportFragmentManager?.executePendingTransactions()
        sdk = instance
        promise.resolve(null)
      } catch (t: Throwable) {
        promise.reject("INIT_ERROR", t)
      }
    }
  }

  override fun registerCustomer(
    userId: String,
    name: String,
    email: String,
    isAnonymous: Boolean,
    env: String?,
    roles: ReadableArray,
    recordWifiOnly: Boolean,
    disableReplaysForUser: Boolean,
    promise: Promise
  ) {
    val s = sdk ?: return promise.reject("REGISTER_ERROR", "init() must be called before registerCustomer().")
    val (region, organisationId) = workspace
      ?: return promise.reject("REGISTER_ERROR", "init() must be called before registerCustomer().")
    val activity = reactApplicationContext.currentActivity
      ?: return promise.reject("REGISTER_ERROR", "No current activity.")
    activity.runOnUiThread {
      try {
        s.register(
          organisationId = organisationId,
          userId = userId,
          // No device id: the backend owns it, so there is nothing for an app to pass.
          deviceId = null,
          name = name,
          email = email,
          region = region,
          // Spelled out rather than taken from FullviewInterface's companion: the SDK ships here as
          // a minified AAR, whose companion object R8 has renamed, so those constants do not resolve
          // from Kotlin. FullviewConfigKeysTest in the SDK pins the spellings.
          additionalConfig = mapOf(
            "fullview-record-wifi-only" to recordWifiOnly.toString(),
            "fullview-disable-replays-for-user" to disableReplaysForUser.toString()
          ),
          env = env,
          roles = roles.toArrayList().filterIsInstance<String>().ifEmpty { null },
          isAnonymous = isAnonymous,
        )
        promise.resolve(null)
      } catch (t: Throwable) {
        promise.reject("REGISTER_ERROR", t)
      }
    }
  }

  override fun logout(promise: Promise) {
    val s = sdk ?: return promise.reject("LOGOUT_ERROR", "attach() not called.")
    s.logout()
    promise.resolve(null)
  }

  override fun requestCoBrowse(promise: Promise) {
    val s = sdk ?: return promise.reject("REQUEST_COBROWSE_ERROR", "attach() not called.")
    s.requestCoBrowse()
    promise.resolve(null)
  }

  /**
   * Resolved rather than rejected before attach: the observer is patched into the app's networking
   * for the whole process, so requests happen before attach and after logout, and a rejection
   * there would surface as a warning on every one of them.
   */
  override fun recordNetworkRequest(payload: String, promise: Promise) {
    sdk?.recordNetworkRequest(payload)
    promise.resolve(null)
  }

  // Like recordNetworkRequest, this is dropped rather than rejected when attach() has not run:
  // an app reporting its screens should not have to care whether recording happens to be on.
  override fun setScreen(name: String, promise: Promise) {
    sdk?.recordScreen(name)
    promise.resolve(null)
  }

  override fun cancelCoBrowseRequest(promise: Promise) {
    val s = sdk ?: return promise.reject("CANCEL_COBROWSE_REQUEST_ERROR", "attach() not called.")
    s.cancelCoBrowseRequest()
    promise.resolve(null)
  }

  override fun getPositionInCoBrowseQueue(promise: Promise) {
    promise.resolve(sdk?.positionInCoBrowseQueue?.replayCache?.lastOrNull() ?: -1)
  }

  /** Same vocabulary as iOS so the JS mapping in sdk-module.tsx works on both. */
  override fun getState(promise: Promise) {
    val state = sdk?.sessionState?.replayCache?.lastOrNull()
    promise.resolve(
      when (state) {
        is FullviewSessionState.CO_BROWSE_ACTIVE -> "CO_BROWSE_ACTIVE"
        is FullviewSessionState.CO_BROWSE_INVITATION -> "CO_BROWSE_INVITATION"
        is FullviewSessionState.CO_BROWSE_REQUESTED -> "CO_BROWSE_REQUESTED"
        else -> "IDLE"
      }
    )
  }

  companion object {
    const val NAME = NativeFullviewSdkSpec.NAME
  }
}
